function voiceRecordingIds(chats) {
    const ids = new Set();
    const addHistory = history => {
        for (const message of history || []) {
            if (message.hasVoiceRecording && typeof message.id === 'string') ids.add(message.id);
        }
    };
    for (const chat of chats) {
        addHistory(chat.history);
        for (const archive of chat.archives || []) addHistory(archive.data?.history);
    }
    return ids;
}

async function encodeVoiceRecording({ id, audio }) {
    const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(audio);
    });
    return { id, dataUrl };
}

function prepareVoiceRecordings(records, chats) {
    if (!Array.isArray(records)) throw new Error('备份中的语音录音格式无效');
    const ids = voiceRecordingIds(chats);
    const result = [];
    for (const { id, dataUrl } of records) {
        if (!ids.delete(id) || typeof dataUrl !== 'string') throw new Error('备份中的语音录音与消息不匹配');
        const match = /^data:(audio\/(?:mp4|webm|ogg|wav|mpeg)(?:;codecs=[\w.,-]+)?);base64,([A-Za-z0-9+/]+={0,2})$/i.exec(dataUrl);
        if (!match) throw new Error('备份中的语音录音格式无效');
        const bytes = Uint8Array.from(atob(match[2]), char => char.charCodeAt(0));
        result.push({ id, audio: new Blob([bytes], { type: match[1] }) });
    }
    return result;
}

// 创建完整的备份数据
async function createFullBackupData({ includeMemory = false } = {}) {
    const backupData = JSON.parse(JSON.stringify(db));
    backupData.theaterRecords = await dexieDB.theaterRecords.toArray();
    backupData._exportVersion = '3.0'; 
    backupData._exportTimestamp = Date.now();
    const voiceIds = [...voiceRecordingIds([...backupData.characters, ...backupData.groups])];
    const recordings = await dexieDB.voiceRecordings.bulkGet(voiceIds);
    backupData.voiceRecordings = await Promise.all(recordings.filter(Boolean).map(encodeVoiceRecording));
    if (includeMemory) backupData.memoryBackups = await memoryRepository.exportAllBackups();
    else {
        for (const character of backupData.characters) {
            delete character.memoryBatchState;
            for (const archive of character.archives || []) {
                if (archive.data) delete archive.data.memoryBatchState;
            }
        }
        for (const group of backupData.groups) {
            delete group.sharedMemory;
            for (const archive of group.archives || []) {
                if (archive.data) delete archive.data.sharedMemory;
            }
        }
    }
    return backupData;
}

// 导入备份数据
async function importBackupData(data, { github = false } = {}) {
    const startTime = Date.now();
    const previousData = github ? structuredClone(db) : { ...db };
    try {
        let convertedData = data;

        if (data._exportVersion !== '3.0') {
            showToast('检测到旧版备份文件，正在转换格式...');
            
            const reassembleHistory = (chat, backupData) => {
                if (!chat.history || !Array.isArray(chat.history) || chat.history.length === 0) {
                    return [];
                }
                if (typeof chat.history[0] === 'object' && chat.history[0] !== null) {
                    return chat.history;
                }
                if (backupData.__chunks__ && typeof chat.history[0] === 'string') {
                    let fullHistory = [];
                    chat.history.forEach(key => {
                        if (backupData.__chunks__[key]) {
                            try {
                                const chunk = JSON.parse(backupData.__chunks__[key]);
                                fullHistory = fullHistory.concat(chunk);
                            } catch (e) {
                                console.error(`Failed to parse history chunk ${key}`, e);
                            }
                        }
                    });
                    return fullHistory;
                }
                return []; 
            };

            const newData = { ...data };

            if (newData.characters) {
                newData.characters = newData.characters.map(char => ({
                    ...char,
                    history: reassembleHistory(char, data)
                }));
            }
            if (newData.groups) {
                newData.groups = newData.groups.map(group => ({
                    ...group,
                    history: reassembleHistory(group, data)
                }));
            }

            // 兼容性处理：将旧版“世界书·中”转换为“世界书·前 + 深度300”
            if (newData.worldBooks && Array.isArray(newData.worldBooks)) {
                newData.worldBooks = newData.worldBooks.map(item => {
                    if (item.type === 'entry' && (item.position === 'middle' || item.position === 'center')) {
                        return {
                            ...item,
                            position: 'before',
                            depth: 300
                        };
                    }
                    return item;
                });
            }
            
            convertedData = newData;
        }

        if (Array.isArray(convertedData.groups)) {
            const previousGroups = new Map(db.groups.map(group => [group.id, group]));
            convertedData = { ...convertedData, groups: convertedData.groups.map(group => {
                const sharedMemory = group.sharedMemory ?? previousGroups.get(group.id)?.sharedMemory;
                return sharedMemory ? { ...group, sharedMemory: memoryGroup.validateMemory(sharedMemory) } : group;
            }) };
        }
        const targetRoleIds = new Set((convertedData.characters ?? db.characters).map(character => character.id));
        const theaterRows = convertedData.theaterRecords === undefined ? null : window.MiniTheater.validateBackup(convertedData.theaterRecords, targetRoleIds);
        const memories = convertedData.memoryBackups === undefined ? null
            : await memoryRepository.prepareAllBackups(convertedData.memoryBackups, targetRoleIds);
        if (memories?.missing) throw new Error('全量备份缺少记忆对应的角色');
        const restoredVoice = convertedData.voiceRecordings === undefined ? []
            : prepareVoiceRecordings(convertedData.voiceRecordings,
                [...(convertedData.characters ?? db.characters), ...(convertedData.groups ?? db.groups)]);

        Object.keys(db).forEach(key => {
            if (convertedData[key] !== undefined) {
                db[key] = convertedData[key];
            }
        });
        
        if (!db.insWidgetSettings) db.insWidgetSettings = { avatar1: 'data:image/jpeg;base64,', bubble1: 'love u.', avatar2: 'data:image/jpeg;base64,', bubble2: 'miss u.' };
        if (!db.homeWidgetSettings) db.homeWidgetSettings = JSON.parse(JSON.stringify(defaultWidgetSettings));


        showToast('正在写入新数据...');
        await dexieDB.transaction('rw', dexieDB.tables, async () => {
            await Promise.all([
                dexieDB.characters.clear(),
                dexieDB.groups.clear(),
                dexieDB.worldBooks.clear(),
                dexieDB.myStickers.clear(),
                github ? Promise.resolve() : dexieDB.globalSettings.clear()
            ]);
            await saveData();
            if (github) {
                const extras = Object.entries(convertedData)
                    .filter(([key]) => !Object.hasOwn(db, key) && !key.startsWith('_') && key !== 'memoryBackups' && key !== 'voiceRecordings' && key !== 'theaterRecords')
                    .map(([key, value]) => ({ key, value }));
                if (extras.length) await dexieDB.globalSettings.bulkPut(extras);
            }
            await memoryRepository.pruneDeletedCharacters();
            if (memories) await memoryRepository.importAllBackups(memories.prepared);
            if (restoredVoice.length) await dexieDB.voiceRecordings.bulkPut(restoredVoice);
            if (theaterRows) { await dexieDB.theaterRecords.clear(); await dexieDB.theaterRecords.bulkPut(theaterRows); }
            await window.MiniTheater.prune();
        });

        const duration = Date.now() - startTime;
        const message = `导入完成 (耗时${duration}ms)`;
        
        return { success: true, message: message };

    } catch (error) {
        Object.assign(db, previousData);
        console.error('导入数据失败:', error);
        return {
            success: false,
            error: error.message,
            duration: Date.now() - startTime
        };
    }
}

// GitHub Manager
const GitHubMgr = {
    config: { token: '', repo: '', auto: false, interval: 48, lastTime: 0, fileName: '' },
    
    init: () => {
        const confStr = localStorage.getItem('gh_config');
        if(confStr) GitHubMgr.config = JSON.parse(confStr);
        
        const tokenInput = document.getElementById('gh-token-input');
        const repoInput = document.getElementById('gh-repo-input');
        const fileNameInput = document.getElementById('gh-filename-input');
        const autoSwitch = document.getElementById('gh-auto-switch');
        
        if(tokenInput) tokenInput.value = GitHubMgr.config.token || '';
        if(repoInput) repoInput.value = GitHubMgr.config.repo || '';
        if(fileNameInput) fileNameInput.value = GitHubMgr.config.fileName || '';
        
        if(autoSwitch) {
            autoSwitch.checked = GitHubMgr.config.auto || false;
            document.getElementById('gh-interval-setting').style.display = autoSwitch.checked ? 'flex' : 'none';
        }
        if(document.getElementById('gh-interval-select')) {
            document.getElementById('gh-interval-select').value = GitHubMgr.config.interval || 48;
        }
        
        if(GitHubMgr.config.auto) GitHubMgr.checkAndBackup();
        GitHubMgr.updateStatusText();
    },
    
    saveConfig: ({ checkAuto = true } = {}) => {
        let token = document.getElementById('gh-token-input').value.trim();
        // 自动清理 Token：移除前缀和空格
        token = token.replace(/^(Bearer|token)\s+/i, '').replace(/\s+/g, '');

        const repo = document.getElementById('gh-repo-input').value.trim();
        const fileName = document.getElementById('gh-filename-input').value.trim();
        const auto = document.getElementById('gh-auto-switch').checked;
        const interval = parseInt(document.getElementById('gh-interval-select').value);
        
        GitHubMgr.config.token = token;
        GitHubMgr.config.repo = repo;
        GitHubMgr.config.fileName = fileName;
        GitHubMgr.config.auto = auto;
        GitHubMgr.config.interval = interval;
        
        document.getElementById('gh-interval-setting').style.display = auto ? 'flex' : 'none';
        
        localStorage.setItem('gh_config', JSON.stringify(GitHubMgr.config));
        GitHubMgr.updateStatusText();
        
        if(auto && checkAuto) GitHubMgr.checkAndBackup();
    },
    
    updateStatusText: () => {
        const el = document.getElementById('gh-status-msg');
        if(!el) return;
        if(!GitHubMgr.config.lastTime) el.innerText = '从未备份过';
        else {
            const date = new Date(GitHubMgr.config.lastTime);
            const nextTime = new Date(GitHubMgr.config.lastTime + (GitHubMgr.config.interval || 48) * 3600000);
            el.innerText = `上次: ${date.toLocaleString()} (下次约: ${nextTime.toLocaleString()})`;
        }
    },
    
    checkAndBackup: async () => {
        if(GitHubMgr.busy || !GitHubMgr.config.token || !GitHubMgr.config.repo || !GitHubMgr.config.auto) return;
        const now = Date.now();
        const interval = GitHubMgr.config.interval || 48;
        const hours = (now - (GitHubMgr.config.lastTime || 0)) / (1000 * 60 * 60);
        
        if(hours >= interval) {
            console.log(`距离上次备份已过 ${hours.toFixed(1)} 小时，触发自动备份...`);
            
            const toast = document.createElement('div');
            toast.style.cssText = 'position:fixed; top:10px; left:50%; transform:translateX(-50%); background:rgba(0,0,0,0.7); color:#fff; padding:8px 15px; border-radius:20px; font-size:12px; z-index:9999; pointer-events:none; transition:opacity 0.5s;';
            toast.innerText = '正在后台准备自动备份...';
            document.body.appendChild(toast);
            
            try {
                await GitHubMgr.performUpload((msg) => { toast.innerText = '自动备份: ' + msg; });
                toast.innerText = '自动备份成功！';
                setTimeout(() => toast.remove(), 3000);
            } catch(e) {
                console.error('自动备份失败', e);
                toast.innerText = '自动备份失败: ' + e.message;
                setTimeout(() => toast.remove(), 5000);
            }
        }
    },
    
    testUpload: async btn => {
        if (GitHubMgr.busy) return showToast('备份或恢复正在进行');
        GitHubMgr.saveConfig({ checkAuto: false });
        if(!GitHubMgr.config.token || !GitHubMgr.config.repo) return alert('请先填写 Token 和 仓库路径');
        showToast('开始备份...');
        const originalText = btn.innerText;
        btn.innerText = '备份中...';
        btn.style.pointerEvents = 'none';
        
        try {
            await GitHubMgr.performUpload((msg) => { showToast(msg); });
            showToast('上传成功！');
        } catch(e) {
            showToast('上传失败: ' + e.message);
        } finally {
            btn.innerText = originalText;
            btn.style.pointerEvents = 'auto';
        }
    },
    
    performUpload: async (onProgress = () => {}) => {
        if (GitHubMgr.busy) throw new Error('备份或恢复正在进行');
        const config = { ...GitHubMgr.config };
        GitHubMgr.busy = true;
        try {
            const manifest = await githubBackup.upload(config, onProgress);
            if (GitHubMgr.config.repo === config.repo && GitHubMgr.config.fileName === config.fileName) {
                GitHubMgr.config.lastTime = Date.now();
                localStorage.setItem('gh_config', JSON.stringify(GitHubMgr.config));
                GitHubMgr.updateStatusText();
            }
            return manifest;
        } finally {
            GitHubMgr.busy = false;
        }
    },

    checkStatus: async () => {
        if(!GitHubMgr.config.token || !GitHubMgr.config.repo) return showToast('未配置');
        const url = `https://api.github.com/repos/${GitHubMgr.config.repo}`;
        try {
            const res = await fetch(url, { headers: { 'Authorization': `token ${GitHubMgr.config.token}` } });
            if(res.ok) {
                const data = await res.json();
                alert(`连接成功！\n仓库: ${data.full_name}\n私有: ${data.private}\n说明: 配置有效`);
            } else {
                alert('连接失败，请检查 Token 或 仓库路径');
            }
        } catch(e) { alert('网络错误: ' + e.message); }
    },
    
    restoreLatest: async btn => {
        if (GitHubMgr.busy) return showToast('备份或恢复正在进行');
        if (!GitHubMgr.config.token || !GitHubMgr.config.repo) return alert('请先在配置中填写 Token 和仓库路径');
        if (!confirm('恢复将用备份内容覆盖本机对应数据。确定继续吗？')) return;
        const originalText = btn.innerText;
        GitHubMgr.busy = true;
        btn.innerText = '恢复中…';
        btn.disabled = true;
        let restored = false;
        try {
            const result = await githubBackup.restoreLatest({ ...GitHubMgr.config }, showToast);
            showToast(result.fallback ? '已恢复上一份完整备份，应用即将刷新。' : '恢复成功，应用即将刷新。');
            restored = true;
            window.location.reload();
        } catch (error) {
            alert('恢复失败: ' + error.message);
        } finally {
            if (!restored) {
                GitHubMgr.busy = false;
                btn.innerText = originalText;
                btn.disabled = false;
            }
        }
    }
};
window.GitHubMgr = GitHubMgr;

// 全局手动备份触发函数
async function triggerManualBackup() {
    if (loadingBtn) return;
    loadingBtn = true;
    try {
        showToast('正在准备导出数据...');

        const fullBackupData = await createFullBackupData({ includeMemory: true });

        const jsonString = JSON.stringify(fullBackupData);
        const dataBlob = new Blob([jsonString]);

        const compressionStream = new CompressionStream('gzip');
        const compressedStream = dataBlob.stream().pipeThrough(compressionStream);
        const compressedBlob = await new Response(compressedStream, { headers: { 'Content-Type': 'application/octet-stream' } }).blob();

        const url = URL.createObjectURL(compressedBlob);
        const a = document.createElement('a');
        const now = new Date();
        const date = now.toISOString().slice(0, 10);
        const time = now.toTimeString().slice(0, 8).replace(/:/g, '');
        a.href = url;
        a.download = `章鱼喷墨_备份数据_${date}_${time}.ee`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        loadingBtn = false;
        showToast('聊天记录导出成功');
        
        // 更新提醒时间
        if (db.backupReminderSettings) {
            db.backupReminderSettings.lastReminderTime = Date.now();
            await saveData();
        }
    } catch (e) {
        loadingBtn = false;
        showToast(`导出失败, 发生错误: ${e.message}`);
        console.error('导出错误详情:', e);
    }
}
window.triggerManualBackup = triggerManualBackup;
;
